-- Galini Academy expansion: Personal Lines, package rating, and advanced commercial lines.
-- Apply after 001 and 002 on the Galini preview Neon database.
INSERT INTO training_courses(title,description,category,level,duration_minutes,is_published)
SELECT v.title,v.description,v.category,v.level,v.duration,true
FROM (VALUES
('Personal Auto Insurance Academy','Learn personal auto underwriting, driver and vehicle data, coverage selection, rating factors and policy review.','Personal Lines','Beginner',100),
('Homeowners Insurance Academy','Practice homeowners property details, reconstruction values, protection, deductibles, liability and underwriting.','Personal Lines','Beginner',100),
('Personal Lines Rating & Coverage Workshop','Compare personal auto, homeowners, renters and personal umbrella coverage and understand rating inputs.','Personal Lines','Intermediate',90),
('Commercial Package & BOP Academy','Learn when to consider a BOP versus a commercial package policy, property and liability sections, eligibility and rating exposures.','Commercial Lines','Intermediate',120),
('Commercial Auto Underwriting & Rating','Practice fleet schedules, driver details, vehicle use, radius, symbols, physical damage and underwriting review.','Commercial Lines','Intermediate',110),
('Workers Compensation & Payroll Rating','Learn payroll by class and state, experience modification, owner inclusion, audits and premium calculations.','Commercial Lines','Intermediate',100),
('Commercial Umbrella & Excess Liability','Understand underlying policies, attachment points, limits, schedules, exclusions and umbrella submission details.','Commercial Lines','Advanced',90),
('Insurance Rating, Quote Comparison & Proposal Skills','Practice rating inputs, premium calculations, coverage comparison, underwriting referrals and client presentations.','Professional Skills','Intermediate',100)
) v(title,description,category,level,duration)
WHERE NOT EXISTS(SELECT 1 FROM training_courses c WHERE c.title=v.title);

INSERT INTO training_lessons(course_id,title,lesson_type,content,sort_order,is_published)
SELECT c.id,v.lesson,'reading',v.content,v.ord,true
FROM (VALUES
('Personal Auto Insurance Academy','Applicant, household and driver discovery','Collect named insureds, household members, licensed and excluded drivers, dates of birth, license state and number where permitted, years licensed, vehicle ownership, garaging address, annual mileage, commute, business use and prior insurance. Ask about youthful operators, rideshare, delivery, business use and out-of-state garaging. Obtain required authorizations before ordering consumer reports or MVRs. Never infer a driver or household member.',1),
('Personal Auto Insurance Academy','Vehicle schedule and symbols','For every vehicle verify year, make, model, VIN, ownership or lease, garaging ZIP, annual mileage, use, safety features and lienholder. Match the vehicle identification to registration and client documents. Understand liability, PIP/no-fault where applicable, uninsured/underinsured motorist, medical payments, comprehensive and collision. Physical damage deductibles and lender requirements must be clear.',2),
('Personal Auto Insurance Academy','Coverage selection and limits','Explain liability limits as per-person/per-accident bodily injury and property damage where applicable. Discuss UM/UIM, PIP or medical payments, rental reimbursement, roadside assistance and physical damage. Do not recommend minimum limits without discussing asset exposure and state requirements. Document declined coverages and selection in writing.',3),
('Personal Auto Insurance Academy','Auto rating and quote review','Rating inputs can include territory, vehicle symbol, driver age and experience, driving history, annual mileage, usage, prior insurance, coverage limits and deductibles. Carrier rating plans differ by state and company. Compare the same drivers, vehicles, limits, deductibles and effective date across offers; review exclusions and underwriting conditions, not premium alone.',4),
('Personal Auto Insurance Academy','Auto practice case and quality control','Build a complete household schedule. Reconcile drivers and vehicles, flag garaging and usage inconsistencies, confirm lienholders and verify the requested effective date. Prepare a client-ready comparison showing limits, deductibles, discounts subject to verification, fees and total premium. Do not promise a discount or bind without carrier confirmation.',5),

('Homeowners Insurance Academy','Dwelling and replacement cost','Confirm property address, year built, square footage, stories, construction, roof shape and age, updates to electrical/plumbing/heating, foundation, attached structures and occupancy. Replacement cost is the estimated cost to rebuild with similar materials and labor, not market value or mortgage balance. Explain valuation assumptions and recommend a professional reconstruction-cost review when appropriate.',1),
('Homeowners Insurance Academy','Coverage A through F','Review Coverage A dwelling, B other structures, C personal property, D loss of use, E personal liability and F medical payments to others. Discuss special limits, scheduled property, water backup, ordinance or law, equipment breakdown and other endorsements as available. Coverage and sublimits vary by form and state; explain what is and is not included.',2),
('Homeowners Insurance Academy','Perils, deductibles and property risks','Identify roof age and material, prior water or fire losses, plumbing, wiring, heating, protective devices, swimming pools, trampolines, animals, wood stoves, vacancy and short-term rental activity. Explain all-peril and separate wind/hail or named-storm deductibles. Flood and earthquake are commonly excluded or separately insured; never imply a standard homeowners policy covers them.',3),
('Homeowners Insurance Academy','Home rating and underwriting review','Home rating may consider territory, replacement cost, construction, roof age, protection class, distance to fire services, claims history, occupancy, deductible and mitigation features. Verify eligibility and underwriting requirements with the carrier. Ask for photos, inspection reports, roof documentation and proof of updates where required.',4),
('Homeowners Insurance Academy','Home quote comparison exercise','Compare Coverage A-F, valuation, deductibles, roof settlement, water exclusions, matching provisions, liability, special limits, endorsements, loss assessment and ordinance/law. Identify coverage gaps and explain them in plain language. Record the insured’s selected option and outstanding underwriting subjectivities.',5),

('Personal Lines Rating & Coverage Workshop','Personal lines account discovery','Start with household composition, locations, property and vehicle schedules, prior insurance, loss history and effective date. Identify exposures requiring separate coverage such as flood, earthquake, scheduled valuables, boats, rental properties or home business. Maintain consistent named insureds and ownership across policies.',1),
('Personal Lines Rating & Coverage Workshop','Renters and condominium coverage','For renters distinguish the tenant’s personal property, liability and additional living expense from the landlord’s building coverage. For condo owners review unit-owner improvements, loss assessment, personal property, liability and master-policy responsibility. Request the association master policy or certificate when needed; do not assume the master policy covers interior improvements.',2),
('Personal Lines Rating & Coverage Workshop','Personal umbrella and underlying limits','A personal umbrella provides excess liability subject to its terms and required underlying limits. Collect all household autos, drivers, residences, watercraft and relevant youthful operators. Verify underlying auto and homeowners liability limits meet the umbrella carrier’s requirements. Review exclusions, retained limits and any required underlying policy schedule.',3),
('Personal Lines Rating & Coverage Workshop','Personal lines quote comparison','Compare identical drivers, vehicles, property values, liability limits, deductibles, endorsements and policy terms. Identify differences in roof settlement, water coverage, UM/UIM, rental, replacement cost and umbrella exclusions. Present the premium alongside meaningful coverage differences, not as the only decision factor.',4),

('Commercial Package & BOP Academy','BOP versus CPP','A businessowners policy is generally a packaged policy designed for eligible small or mid-sized risks with standardized property and liability components. A commercial package policy can combine separately selected coverage parts and may accommodate more varied exposures. Eligibility, forms and package rules vary by carrier. Refer unusual or ineligible risks for underwriting guidance.',1),
('Commercial Package & BOP Academy','Property schedule and valuation','Collect building, business personal property, stock, tenant improvements, business income and extra expense values by location. Confirm occupancy, construction, protection, roof, updates, square footage and operations. Select replacement cost or actual cash value with the insured and explain valuation and coinsurance implications. Separate each location and coverage part clearly.',2),
('Commercial Package & BOP Academy','General liability and package sections','Describe premises/operations, products/completed operations, contractual exposures and subcontractors. Review occurrence and aggregate limits, products aggregate, personal and advertising injury, damage to rented premises and medical payments. Identify whether professional, cyber, employment practices, liquor, auto or workers compensation requires separate coverage.',3),
('Commercial Package & BOP Academy','Package rating and underwriting factors','Common rating inputs include class code, annual sales, payroll, square footage, building values, construction, protection, territory, loss history, limits and deductibles. The exposure basis and rate are carrier-specific. Reconcile all schedules and supplements before presenting a simulated or actual carrier indication.',4),
('Commercial Package & BOP Academy','BOP and CPP case study','Prepare two practice scenarios: a small eligible office/retail risk for BOP screening and a multi-location or more complex operation for CPP discussion. Identify missing information, coverage parts, subjectivities and referral questions. Explain why the selected package structure fits the exposures.',5),

('Commercial Auto Underwriting & Rating','Fleet and vehicle schedule','Record year, make, model, VIN, stated value, ownership, garaging, radius, use, GVW where applicable, vehicle type, trailer details and requested liability/physical damage. Identify owned, hired and non-owned exposures. Verify the schedule against registrations and client records. Note leased vehicles and loss payees.',1),
('Commercial Auto Underwriting & Rating','Driver and motor vehicle review','Collect driver roster, license state and class, experience, hire date, vehicle assignment and required MVR authorization. Ask about inexperienced drivers, violations, accidents, suspensions and out-of-state licenses. Carrier eligibility and driver acceptability differ; disclose material information and do not make assumptions based on job title.',2),
('Commercial Auto Underwriting & Rating','Use, radius, symbols and coverages','Clarify local, intermediate and long-haul radius, delivery, service, for-hire, passenger transport and interstate operations. Review covered auto symbols, liability, comprehensive, collision, towing, rental and hired/non-owned auto. Explain that symbols and endorsements determine which autos qualify; a vehicle schedule alone does not define coverage.',3),
('Commercial Auto Underwriting & Rating','Commercial auto rating practice','Rating can reflect vehicle class and size, radius, use, territory, driver characteristics, loss history, limits, deductibles and fleet size. Use carrier-specific manuals for actual rates. For training, create a transparent estimate, show each exposure assumption and explain why the estimate is not a carrier quote.',4),
('Commercial Auto Underwriting & Rating','Fleet submission and bind checklist','Reconcile VINs, garaging, radius, driver assignment, lienholders and coverage symbols. Confirm filings, certificates, state-specific requirements and required down payment. Binding requires authorized confirmation and completed subjectivities. Check the binder against the accepted quote and fleet schedule.',5),

('Workers Compensation & Payroll Rating','Payroll and classification basics','Collect payroll by state and job duties, not just job title. Separate clerical, sales, field, construction, delivery and other materially different duties as required by the rating bureau and carrier. Record owner/officer status and applicable inclusion or exclusion elections. Verify subcontractor costs and certificates where relevant.',1),
('Workers Compensation & Payroll Rating','Manual premium calculation','A simplified training calculation is payroll divided by 100 multiplied by the manual rate, then adjusted by applicable experience modification, schedule credits/debits, assessments and carrier factors. Actual rules, minimum premiums, split payroll and state assessments vary. Never use a classroom formula as an insurer’s final premium.',2),
('Workers Compensation & Payroll Rating','Experience modification and audits','Explain that an experience modification compares an employer’s historical loss experience with expected experience under the applicable bureau plan. Review current mod worksheets when available. Payroll audits reconcile estimated exposures to actual payroll and duties; explain the importance of accurate records and timely responses.',3),
('Workers Compensation & Payroll Rating','WC submission quality review','Confirm states of operation, FEIN, legal entity, ownership, payroll by class, duties, subcontractors, prior carrier, loss runs and experience modification. Flag employees working in multiple states or duties. Review any required state forms and officer elections. Do not classify work solely to reduce premium.',4),

('Commercial Umbrella & Excess Liability','Underlying policies and limits','Collect underlying general liability, commercial auto, employers liability and any other required policies. Verify carrier, policy number, term, limits, forms and exclusions. Umbrella attachment requirements vary. A limit shown on a certificate does not replace review of the actual underlying policy and endorsements.',1),
('Commercial Umbrella & Excess Liability','Umbrella versus excess','Umbrella coverage may provide broader terms than a pure follow-form excess policy, subject to its own wording and exclusions. Excess coverage generally follows specified underlying coverage more closely. Review attachment points, retained limits, drop-down wording, defense provisions and exhaustion requirements.',2),
('Commercial Umbrella & Excess Liability','Exposure and underwriting details','Collect sales, payroll, fleet units, radius, locations, products, subcontractors, operations, contracts, claims and loss runs. Disclose high-hazard operations, professional services, liquor, residential work, height/depth exposures and other unusual risks. The carrier may require supplemental applications or minimum underlying limits.',3),
('Commercial Umbrella & Excess Liability','Umbrella submission and quote review','Schedule all underlying policies and compare umbrella limit, attachment, exclusions, defense, retained limits and premium. Identify gaps where an underlying policy does not meet requirements. Confirm all subjectivities and written carrier approval before binding.',4),

('Insurance Rating, Quote Comparison & Proposal Skills','How rating plans work','Insurers develop state- and product-specific rating plans using exposure bases, classification rates, factors, minimum premiums, credits, debits and underwriting rules. Some factors are filed or regulated. Agents should use authorized carrier rating tools and current manuals for real business. A training calculator is only a learning aid.',1),
('Insurance Rating, Quote Comparison & Proposal Skills','Build an auditable estimate','Record every input, source, assumption and effective date. Show base premium, exposure basis, selected factors, minimum premium and any taxes or fees separately. Do not hide rounding or apply an unexplained discount. Make it possible for another reviewer to reproduce the practice calculation.',2),
('Insurance Rating, Quote Comparison & Proposal Skills','Compare coverage and total cost','Compare policy forms, limits, sublimits, deductibles, valuation, endorsements, exclusions, subjectivities, taxes, fees and payment plans. Explain annual premium separately from down payment and installments. Show material differences clearly and avoid claiming two policies are equivalent when their forms differ.',3),
('Insurance Rating, Quote Comparison & Proposal Skills','Underwriting referral and proposal','Prepare a concise risk summary, exposure schedule, loss narrative, corrective actions, requested terms and open questions. Identify specialist-market referrals early. Present alternatives and coverage trade-offs in plain language, document the insured’s choice, and distinguish quote, bind request, binder and issued policy.',4)
) v(course_title,lesson,content,ord)
JOIN training_courses c ON c.title=v.course_title
WHERE NOT EXISTS(SELECT 1 FROM training_lessons l WHERE l.course_id=c.id AND l.title=v.lesson);

INSERT INTO training_assessments(course_id,title,instructions,passing_score,questions,is_published)
SELECT c.id,v.title,'Pass with 80%. Review each lesson before answering.',80,v.questions::jsonb,true
FROM (VALUES
('Personal Auto Insurance Academy','Personal Auto Assessment','[{"prompt":"Which details belong on a vehicle schedule?","choices":["VIN, garaging and use","Only vehicle color","Only monthly payment"],"correct":0},{"prompt":"When should MVR authorization be obtained?","choices":["As required before ordering the report","After binding every time","Never"],"correct":0},{"prompt":"What is the correct way to compare two auto offers?","choices":["Same drivers, vehicles, limits and deductibles","Premium only","Different effective dates"],"correct":0}]'),
('Homeowners Insurance Academy','Homeowners Assessment','[{"prompt":"Replacement cost is best described as:","choices":["Estimated cost to rebuild","Market value","Mortgage balance"],"correct":0},{"prompt":"Which is commonly excluded from a standard homeowners policy?","choices":["Flood","Fire","Wind (subject to form)"],"correct":0},{"prompt":"Which coverage is personal liability?","choices":["Coverage E","Coverage A","Coverage C"],"correct":0}]'),
('Personal Lines Rating & Coverage Workshop','Personal Lines Assessment','[{"prompt":"A personal umbrella generally requires:","choices":["Specified underlying liability limits","No underlying policies","Only renters insurance"],"correct":0},{"prompt":"Condo unit-owner coverage should consider:","choices":["Master policy responsibility and unit improvements","Only building market value","Only auto liability"],"correct":0},{"prompt":"Personal quote comparisons should align:","choices":["Limits, deductibles and exposures","Only company names","Only payment dates"],"correct":0}]'),
('Commercial Package & BOP Academy','BOP and CPP Assessment','[{"prompt":"A BOP is generally designed for:","choices":["Eligible small or mid-sized risks","Every commercial risk","Personal auto households"],"correct":0},{"prompt":"Property schedules should separate:","choices":["Building, BPP and business income","All values into one guessed amount","Premium and commission"],"correct":0},{"prompt":"Which exposure may need separate coverage?","choices":["Commercial auto","Office stationery","Agent email"],"correct":0}]'),
('Commercial Auto Underwriting & Rating','Commercial Auto Assessment','[{"prompt":"Commercial auto underwriting should collect:","choices":["VIN, garaging, radius, use and driver roster","Only vehicle color","Only annual revenue"],"correct":0},{"prompt":"Covered auto symbols determine:","choices":["Which autos qualify under the coverage part","Driver payroll","Building occupancy"],"correct":0},{"prompt":"An MVR should be ordered:","choices":["With required authorization and in accordance with rules","Without consent","Only after a loss"],"correct":0}]'),
('Workers Compensation & Payroll Rating','Workers Compensation Assessment','[{"prompt":"Payroll should be organized primarily by:","choices":["State and actual job duties/classification","Employee age","Office location nickname"],"correct":0},{"prompt":"A simplified manual premium formula is:","choices":["Payroll divided by 100 times manual rate","Sales times deductible","Premium divided by limits"],"correct":0},{"prompt":"Payroll audits compare:","choices":["Estimated exposures with actual payroll and duties","Commission with taxes","Vehicle VINs"],"correct":0}]'),
('Commercial Umbrella & Excess Liability','Umbrella Assessment','[{"prompt":"An umbrella submission needs:","choices":["Underlying policy schedules and limits","Only applicant logo","Only property values"],"correct":0},{"prompt":"Excess coverage generally:","choices":["Follows specified underlying coverage more closely","Always broadens every exclusion","Replaces all underlying policies"],"correct":0},{"prompt":"A certificate alone:","choices":["Does not replace review of underlying policies","Always proves every condition","Is a binder for umbrella"],"correct":0}]'),
('Insurance Rating, Quote Comparison & Proposal Skills','Insurance Rating & Proposal Assessment','[{"prompt":"A training rating calculator is:","choices":["An educational aid, not an insurer quote","A filed carrier manual","A binder"],"correct":0},{"prompt":"A quote comparison should include:","choices":["Forms, limits, exclusions, deductibles and total cost","Premium only","Agent preference only"],"correct":0},{"prompt":"A bind request means:","choices":["Request to bind, not proof coverage is bound","Automatic coverage","A policy issuance"],"correct":0}]')
) v(course_title,title,questions)
JOIN training_courses c ON c.title=v.course_title
WHERE NOT EXISTS(SELECT 1 FROM training_assessments a WHERE a.course_id=c.id);
